scenarios.example_code:
import { registerRoute } from '@projexlight/sdk-approval';
await registerRoute({
  tenant_id, name: 'payment-over-10k',
  trigger: { sku: 'payment.charge', condition: 'amount_cents > 1000000' },
  steps: [
    { role: 'finance-reviewer', sla_minutes: 240 },
    { role: 'finance-senior',   sla_minutes: 240 },
  ],
  escalation_persona_id,
});

import { decide } from '@projexlight/sdk-approval';
await decide({
  step_id, decided_by_persona_id,
  outcome: 'approve',
  comment: 'Verified counterparty; ABA matches the W-9 on file.',
});

import { startSlaWatcher } from '@projexlight/sdk-approval';
const worker = startSlaWatcher({ intervalMs: 60_000 });
// graceful shutdown:
await worker.stop();

import { decide } from '@projexlight/sdk-approval';
// Bot persona owns its own persona_id.
await decide({
  step_id, decided_by_persona_id: BOT_PERSONA_ID,
  outcome: requester_persona_id === BOT_PERSONA_ID ? 'reject' : 'approve',
  comment: 'SOD check: requester !== approver',
});

import { requestApproval } from '@projexlight/sdk-approval';
const { request_id } = await requestApproval({
  tenant_id, requester_persona_id,
  route_name: 'destructive-tenant-action',
  action: { kind: 'bulk-delete', table: 'crm.lead', filter: { older_than_days: 365 } },
});
// UI shows 'pending approval'; on approve event the actual delete fires.
